SELECT e.EncounterKey AS encounter_key, h.PAT_ENC_CSN_ID AS clarity_csn, h.PAT_ID AS patient_id, e.FacilityKey AS facility_key, f.FacilityName AS facility_name, h.HOSP_ADMSN_TIME AS admit_at, h.HOSP_DISCH_TIME AS discharge_at, CAST(strftime('%s', h.HOSP_DISCH_TIME) AS INTEGER) - CAST(strftime('%s', h.HOSP_ADMSN_TIME) AS INTEGER) AS los_seconds, CASE h.ADMIT_TYPE_C WHEN 'EMERG' THEN 'unplanned' WHEN 'SCHED' THEN 'planned' END AS admit_kind, CASE h.ADMIT_SOURCE_C WHEN 'DIRECT' THEN 'community' WHEN 'TRANSFER' THEN 'transfer' END AS admit_source, CASE h.DISCH_DISPOSITION_C WHEN 'EXPIRED' THEN 'expired' WHEN 'HOME' THEN 'home' WHEN 'TRANSFER' THEN 'transfer' END AS disposition FROM raw_caboodle_encounter_fact e JOIN raw_clarity_pat_enc_hsp h ON e.ClarityEncounterId = h.PAT_ENC_CSN_ID JOIN raw_caboodle_patient_dim p ON e.PatientDurableKey = p.PatientDurableKey AND p.ClarityPatId = h.PAT_ID JOIN raw_caboodle_facility_dim f ON e.FacilityKey = f.FacilityKey
